mapper.select:
SELECT ia.issue_id AS issueId, e.user_id AS userId, e.name AS name FROM issue_assign ia JOIN employee e ON e.user_id = ia.user_id WHERE ia.issue_id IN
#{issueId}
ORDER BY ia.issue_id DESC, ia.issue_assign_id ASC

SELECT ib.issue_id AS issueId, b.block_id AS blockId, b.title AS title, b.type AS type FROM issue_block ib JOIN block b ON b.block_id = ib.block_id AND b.deleted_at IS NULL WHERE ib.issue_id IN
#{issueId}
ORDER BY ib.issue_id DESC, ib.issue_block_id ASC
